tac_by_country = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= "2023-01-01")
).PARTITION(
    name="countries", by=country
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

result = Cars.WHERE(LOWER(make) == LOWER('Toyota')).sale_records.WHERE(
    DATEDIFF("days", sale_date, DATETIME('now')) <= 30
).CALCULATE(
    number_of_sales=COUNT(Sales),
    total_revenue=SUM(sale_price)
).SINGULAR()

toyota_sales_last_30_days = Cars.WHERE(
