result = Ewallet.CALCULATE(
    num_transactions=COUNT(
        Users.WHERE(LOWER(country) == LOWER("US")).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME("now")) <= 7
        )
    ),
    total_amount=SUM(
        Users.WHERE(LOWER(country) == LOWER("US")).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME("now")) <= 7
        ).amount
    )
)

